-- The CRM becomes the indicator admin panel.
--
-- Everything from the student CRM is deleted on purpose, data included:
-- contacts and leads, programs, batches, sessions, attendance, enrollments,
-- fees and payments, imports, notes and messaging. Indicator subscribers and
-- their payments are not in this database (they live in shubztrader-payments),
-- so nothing here touches them.
--
-- Kept: sign-in accounts (user, account, session, verification) and the audit
-- log's record of team changes.
--
-- Generated by drizzle-kit, then edited by hand: IF EXISTS on every drop so a
-- database missing an old table still migrates, the view dropped first, and the
-- data changes for the audit log and team accounts marked below.

DROP VIEW IF EXISTS "enrollment_balances";--> statement-breakpoint
DROP TABLE IF EXISTS "consent_events" CASCADE;--> statement-breakpoint
DROP TABLE IF EXISTS "contact_tags" CASCADE;--> statement-breakpoint
DROP TABLE IF EXISTS "contacts" CASCADE;--> statement-breakpoint
DROP TABLE IF EXISTS "tags" CASCADE;--> statement-breakpoint
DROP TABLE IF EXISTS "batches" CASCADE;--> statement-breakpoint
DROP TABLE IF EXISTS "sessions" CASCADE;--> statement-breakpoint
DROP TABLE IF EXISTS "programs" CASCADE;--> statement-breakpoint
DROP TABLE IF EXISTS "attendance" CASCADE;--> statement-breakpoint
DROP TABLE IF EXISTS "enrollments" CASCADE;--> statement-breakpoint
DROP TABLE IF EXISTS "payment_schedule" CASCADE;--> statement-breakpoint
DROP TABLE IF EXISTS "payments" CASCADE;--> statement-breakpoint
DROP TABLE IF EXISTS "import_rows" CASCADE;--> statement-breakpoint
DROP TABLE IF EXISTS "imports" CASCADE;--> statement-breakpoint
DROP TABLE IF EXISTS "notes" CASCADE;--> statement-breakpoint
DROP TABLE IF EXISTS "campaign_recipients" CASCADE;--> statement-breakpoint
DROP TABLE IF EXISTS "campaigns" CASCADE;--> statement-breakpoint
DROP TABLE IF EXISTS "message_events" CASCADE;--> statement-breakpoint
DROP TABLE IF EXISTS "message_templates" CASCADE;--> statement-breakpoint
DROP TABLE IF EXISTS "messages" CASCADE;--> statement-breakpoint
DROP TABLE IF EXISTS "scheduled_jobs" CASCADE;--> statement-breakpoint
DROP TABLE IF EXISTS "webhook_events" CASCADE;--> statement-breakpoint
-- Hand-written: old audit entries carry copies of the deleted records. Keep only team changes.
DELETE FROM "audit_log" WHERE "entity" <> 'user';--> statement-breakpoint
ALTER TABLE "audit_log" ALTER COLUMN "entity_id" SET DATA TYPE text;--> statement-breakpoint
ALTER TABLE "user" ALTER COLUMN "role" SET DATA TYPE text;--> statement-breakpoint
-- Hand-written: only SUPERADMIN and ADMIN remain. Manager and operator accounts are
-- switched off and kept as ADMIN, so nobody gains access to buyer data by default.
UPDATE "user" SET "active" = false WHERE "role" NOT IN ('SUPERADMIN', 'ADMIN');--> statement-breakpoint
UPDATE "user" SET "role" = 'ADMIN' WHERE "role" NOT IN ('SUPERADMIN', 'ADMIN');--> statement-breakpoint
ALTER TABLE "user" ALTER COLUMN "role" SET DEFAULT 'ADMIN'::text;--> statement-breakpoint
DROP TYPE "public"."user_role";--> statement-breakpoint
CREATE TYPE "public"."user_role" AS ENUM('SUPERADMIN', 'ADMIN');--> statement-breakpoint
ALTER TABLE "user" ALTER COLUMN "role" SET DEFAULT 'ADMIN'::"public"."user_role";--> statement-breakpoint
ALTER TABLE "user" ALTER COLUMN "role" SET DATA TYPE "public"."user_role" USING "role"::"public"."user_role";--> statement-breakpoint
-- Hand-written: the old permission names mean nothing now; everyone follows their role.
UPDATE "user" SET "permissions" = NULL WHERE "permissions" IS NOT NULL;--> statement-breakpoint
-- Hand-written: the superadmin decides who sees buyer data. Admin accounts from the
-- old CRM are switched off (not deleted) and can be switched back on from Team.
-- Skipped when there is no active superadmin, so nobody is locked out.
UPDATE "user" SET "active" = false
WHERE "role" = 'ADMIN'
  AND EXISTS (SELECT 1 FROM "user" AS s WHERE s."role" = 'SUPERADMIN' AND s."active");--> statement-breakpoint
